def _clean(v):
    if isinstance(v, (np.integer,)):
        return int(v)
    if isinstance(v, (np.bool_,)):
        return bool(v)
    if isinstance(v, (float,np.floating)):
        return float(v) if np.isfinite(v) else None
    if isinstance(v, pd.Timestamp):
        return v.isoformat()
    return v


def _safe_json(value):
    # Handle NaN and literal closing script tags in user-provided text.
    def walk(v):
        if isinstance(v,dict): return {str(k):walk(x) for k,x in v.items()}
        if isinstance(v,(list,tuple)): return [walk(x) for x in v]
        return _clean(v)
    return json.dumps(walk(value),ensure_ascii=False,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')


def build_dashboard(features, scores, metrics, manifest, overview, out_path, unavailable=None, extras=None, share=False):
    df=features.merge(scores,on='employee_id',how='left')
    for c in ('division_name','org_unit_name','grade_title','name','role_title','employment_type','employment_status'):
        df[c]=df[c].fillna('미지정') if c in df else '미지정'
    ov=dict(overview)
    if share:
        ids=df.sort_values('risk_score',ascending=False).employee_id.tolist()
        aliases={eid:f'P-{i+1:03d}' for i,eid in enumerate(ids)}
        df['employee_id']=df.employee_id.map(aliases);df['name']='비식별'
        # Only retain aggregates and identifier-remapped series actually used by the UI.
        ov={k:[{**r,'employee_id':aliases[r['employee_id']]} for r in overview.get(k,[]) if r['employee_id'] in aliases]
            for k in ('monthly_by_employee','survey_by_employee')}
        # Free text validation details may include original names/IDs.
        extras={'checklist':[dict(id=c['id'],item=c['item'],status_ko=c['status_ko'],detail='공유용: 상세 근거는 HR 원본에서 확인') for c in (extras or {}).get('checklist',[])]}
    feats=[c for c in ALLOWED_FEATURES if c in df and df[c].notna().any()]
    ev=metrics.get('evaluation')
    if share and ev:
        ev={k:v for k,v in ev.items() if k not in ("source_hashes", "label_exclusions")}
    company=manifest['company']['name']
    meta=dict(company=company,company_key=hashlib.sha256(str(manifest.get('company_id') or company).encode()).hexdigest()[:24],
              as_of=str(manifest.get('as_of')),mode=metrics.get('mode','heuristic'),share=share,
              synthetic=bool((ev or {}).get('synthetic')) or '픽스처' in company,
              reference=metrics.get('reference_medians',{}),band_method=metrics.get('band_method',''),
              target=(ev or {}).get('target'),horizon_days=(ev or {}).get('horizon_days'),evaluation=ev)
    replacements={'__DATA__':dict(rows=df.to_dict('records'),feats=feats),'__DOCS__':FEATURE_DOCS,
                  '__OVERVIEW__':ov,'__EXTRAS__':extras or {},'__META__':meta}
    html=TEMPLATE
    for marker,value in replacements.items(): html=html.replace(marker,_safe_json(value))
    out_path=Path(out_path);out_path.write_text(html,encoding='utf-8');return out_path
